  ('Tras la Guerra del Pacífico, Chile incorporó:', 55, 'Rapa Nui', 'la Patagonia', 'la Araucanía', 'Tarapacá y Antofagasta, ricas en salitre', 'D', 'El salitre se convirtió en la principal riqueza del país.'),
  ('¿Cuándo se formó la Primera Junta Nacional de Gobierno?', 55, 'El 12 de febrero de 1818', 'El 18 de septiembre de 1810', 'El 5 de abril de 1818', 'El 1 de enero de 1810', 'B', 'Es el inicio del proceso de independencia.'),
  ('¿Qué potencias se enfrentaron en la Guerra Fría?', 56, 'Estados Unidos y la URSS', 'China y Japón', 'Reino Unido y Estados Unidos', 'Alemania y Francia', 'A', 'Representaban el capitalismo y el comunismo.'),
  ('¿En qué año triunfó la Revolución cubana?', 56, '1973', '1945', '1989', '1959', 'D', 'Liderada por Fidel Castro.'),
  ('La crisis de los misiles ocurrió en:', 56, '1950, en Corea', '1989, en Berlín', '1979, en Afganistán', '1962, por la instalación de misiles soviéticos en Cuba', 'D', 'Fue el momento de mayor riesgo de guerra nuclear.'),
  ('¿En qué año cayó el Muro de Berlín?', 56, '1991', '1975', '1961', '1989', 'D', 'Anticipó el fin de la Guerra Fría.'),
  ('¿Qué alianza militar occidental se creó en 1949?', 56, 'La OTAN', 'El Pacto de Varsovia', 'La OEA', 'La ONU', 'A', 'El Pacto de Varsovia fue la respuesta soviética en 1955.'),
  ('En un Estado de derecho:', 57, 'gobernantes y gobernados se someten a la ley', 'solo los ciudadanos deben cumplir la ley', 'el Presidente está por sobre la ley', 'no existen tribunales', 'A', 'Nadie está por sobre el ordenamiento jurídico.'),
  ('¿Qué poder del Estado discute y aprueba las leyes en Chile?', 57, 'Únicamente el Ejecutivo', 'La Contraloría', 'El Judicial', 'El Legislativo (Congreso Nacional)', 'D', 'El Presidente también participa como colegislador.'),
  ('La separación de poderes busca:', 57, 'evitar la concentración del poder', 'eliminar el Congreso', 'reemplazar las elecciones', 'acelerar las decisiones del Presidente', 'A', 'Cada poder controla a los otros.'),
  ('¿Qué organismo controla la legalidad de los actos de la administración del Estado?', 57, 'La Contraloría General de la República', 'El Senado', 'El Servel', 'El Banco Central', 'A', 'Es un organismo autónomo.'),
  ('¿Cuál es una característica de la democracia?', 57, 'Un partido único', 'La sucesión hereditaria del poder', 'Elecciones periódicas, libres y competitivas', 'La censura de prensa', 'C', 'Permite que la ciudadanía elija a sus autoridades.'),
  ('¿Cuándo y quién adoptó la Declaración Universal de los Derechos Humanos?', 58, 'La ONU, en 1948', 'Los Aliados, en Yalta en 1945', 'Francia, en 1789', 'Chile, en 1991', 'A', 'Fue aprobada el 10 de diciembre de 1948.'),
  ('Que los derechos humanos sean universales significa que:', 58, 'solo los tienen los adultos', 'solo los tienen quienes pueden votar', 'pertenecen a todas las personas sin distinción', 'solo existen en países democráticos', 'C', 'No dependen de nacionalidad, edad ni condición.'),
  ('El derecho a la educación pertenece a los derechos de:', 58, 'segunda generación (económicos, sociales y culturales)', 'tercera generación', 'ninguna generación', 'primera generación', 'A', 'Requiere acciones del Estado para garantizarse.'),
  ('El derecho a vivir en un medio ambiente sano es un derecho de:', 58, 'primera generación', 'ninguna: no es un derecho humano', 'tercera generación (solidaridad)', 'segunda generación', 'C', 'Son derechos colectivos.'),
  ('¿Quién es el principal garante de los derechos humanos?', 58, 'Las empresas privadas', 'Cada familia', 'Únicamente las ONG', 'El Estado', 'D', 'Tiene el deber de respetarlos y protegerlos.'),
  ('En Chile son ciudadanos:', 59, 'solo quienes votaron en la última elección', 'los mayores de 21 años', 'los chilenos mayores de 18 años no condenados a pena aflictiva', 'todos los habitantes del país', 'C', 'Así lo establece la Constitución.'),
  ('¿Cuál de las siguientes es una forma de participación no electoral?', 59, 'Ser candidato a diputado', 'Votar en un plebiscito', 'Integrar una junta de vecinos', 'Votar en una elección presidencial', 'C', 'No implica votar ni ser candidato.'),
  ('¿Qué ley permite solicitar información a los organismos públicos?', 59, 'La Ley de Lobby', 'La Ley REP', 'La Ley de Transparencia', 'El Código del Trabajo', 'C', 'Garantiza el acceso a la información pública.'),
  ('El voto secreto busca:', 59, 'proteger la libertad del elector', 'acelerar el conteo de votos', 'impedir que voten los jóvenes', 'que todos sepan por quién votó cada persona', 'A', 'Evita presiones sobre el votante.'),
  ('Un centro de estudiantes es un ejemplo de:', 59, 'participación en organizaciones sociales', 'un organismo autónomo del Estado', 'un partido político', 'un poder del Estado', 'A', 'Representa a los estudiantes de un establecimiento.')
) AS e(enunciado, id_tema, alt_a, alt_b, alt_c, alt_d, respuesta_correcta, retroalimentacion)
WHERE NOT EXISTS (SELECT 1 FROM ejercicios x WHERE x.id_tema = e.id_tema);

SELECT setval(pg_get_serial_sequence('ramas', 'id'), (SELECT max(id) FROM ramas));
SELECT setval(pg_get_serial_sequence('temas', 'id'), (SELECT max(id) FROM temas));

COMMIT;
